(7599405, 1227322, 22734, '<td valign="top">A magical fascination. Nice work. Congrats on top 10 finish.</td>', 'A magical fascination. Nice work. Congrats on top 10 finish.', '2018-10-24 17:26:37.000000', NULL, 0),
(7599406, 1227419, 22734, '<td valign="top">A busy image but it works because the eyes find satisfaction on the different renderings of the model. Also, the image has a wonderful loose feel of an art workshop. Congrats on top ten finish.</td>', 'A busy image but it works because the eyes find satisfaction on the different renderings of the model. Also, the image has a wonderful loose feel of an art workshop. Congrats on top ten finish.', '2018-10-24 17:32:41.000000', NULL, 0),
